pathsBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "pathsBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "pathlab",
                name = "paths",
                version = c(0,4,6),
                options = options,
                results = pathsResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' Mediation and Moderation
#'
#' Choose the original or general graph editor. Select variables, explicit 
#' arrows and their moderator attachments. General graphs support up to ten 
#' continuous mediators and three moderators, subject to path and computation 
#' budgets.
#' @param data .
#' @param x .
#' @param m1 .
#' @param m2 .
#' @param y .
#' @param w .
#' @param p_x_m1 .
#' @param p_x_m2 .
#' @param p_m1_m2 .
#' @param p_x_y .
#' @param p_m1_y .
#' @param p_m2_y .
#' @param p_w_m1 .
#' @param p_w_m2 .
#' @param p_w_y .
#' @param mod_x_m1 .
#' @param mod_x_m2 .
#' @param mod_m1_m2 .
#' @param mod_x_y .
#' @param mod_m1_y .
#' @param mod_m2_y .
#' @param robust .
#' @param draws .
#' @param seed .
#' @param confidence .
#' @param probes .
#' @param showDetails .
#' @param showCovariance .
#' @param covM1 .
#' @param covM2 .
#' @param covY .
#' @param modelMode .
#' @param generalMediators .
#' @param generalModerators .
#' @param generalCovariates .
#' @param generalPaths .
#' @param generalModerations .
#' @param generalProbesW .
#' @param generalProbesZ .
#' @param generalProbesV .
#' @param categoricalCoding .
#' @param outcomeFamily .
#' @param logisticEvent .
#' @param showEffectPlot .
#' @param showInteractionPlot .
#' @param showJNPlot .
#' @param plotInteractionMode .
#' @param plotInteractionPage .
#' @param plotEffectKind .
#' @param plotEffectPage .
#' @param plotSource .
#' @param plotTarget .
#' @param plotModerator .
#' @param plotCondition .
#' @param plotContrast .
#' @param plotResponseScale .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$review} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$diagram} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$equations} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$estimates} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effectPages} \tab \tab \tab \tab \tab an array of tables \cr
#'   \code{results$simpleSlopes} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$jn} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$covariance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coding} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$logisticFit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$diagnostics} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$reproduction} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$plotNotes} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$effectPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$interactionPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$jnPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$interactionPlots} \tab \tab \tab \tab \tab an array of images \cr
#'   \code{results$fitCache} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$equations$asDF}
#'
#' \code{as.data.frame(results$equations)}
#'
#' @export
paths <- function(
    data,
    x,
    m1 = NULL,
    m2 = NULL,
    y,
    w = NULL,
    p_x_m1 = TRUE,
    p_x_m2 = TRUE,
    p_m1_m2 = TRUE,
    p_x_y = TRUE,
    p_m1_y = TRUE,
    p_m2_y = TRUE,
    p_w_m1 = TRUE,
    p_w_m2 = FALSE,
    p_w_y = FALSE,
    mod_x_m1 = TRUE,
    mod_x_m2 = FALSE,
    mod_m1_m2 = FALSE,
    mod_x_y = FALSE,
    mod_m1_y = FALSE,
    mod_m2_y = FALSE,
    robust = TRUE,
    draws = 1000,
    seed = 419,
    confidence = 95,
    probes = "",
    showDetails = FALSE,
    showCovariance = FALSE,
    covM1 = NULL,
    covM2 = NULL,
    covY = NULL,
    modelMode = "legacy",
    generalMediators = NULL,
    generalModerators = NULL,
    generalCovariates = NULL,
    generalPaths = list(),
    generalModerations = list(),
    generalProbesW = "",
    generalProbesZ = "",
    generalProbesV = "",
    categoricalCoding = list(),
    outcomeFamily = "linear",
    logisticEvent = "",
    showEffectPlot = FALSE,
    showInteractionPlot = FALSE,
    showJNPlot = FALSE,
    plotInteractionMode = "selected",
    plotInteractionPage = 1,
    plotEffectKind = "specific_indirect",
    plotEffectPage = 1,
    plotSource = "X",
    plotTarget = "Y",
    plotModerator = "W",
    plotCondition = 1,
    plotContrast = 1,
    plotResponseScale = "response") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("paths requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if ( ! missing(m1)) m1 <- jmvcore::resolveQuo(jmvcore::enquo(m1))
    if ( ! missing(m2)) m2 <- jmvcore::resolveQuo(jmvcore::enquo(m2))
    if ( ! missing(y)) y <- jmvcore::resolveQuo(jmvcore::enquo(y))
    if ( ! missing(w)) w <- jmvcore::resolveQuo(jmvcore::enquo(w))
    if ( ! missing(covM1)) covM1 <- jmvcore::resolveQuo(jmvcore::enquo(covM1))
    if ( ! missing(covM2)) covM2 <- jmvcore::resolveQuo(jmvcore::enquo(covM2))
    if ( ! missing(covY)) covY <- jmvcore::resolveQuo(jmvcore::enquo(covY))
    if ( ! missing(generalMediators)) generalMediators <- jmvcore::resolveQuo(jmvcore::enquo(generalMediators))
    if ( ! missing(generalModerators)) generalModerators <- jmvcore::resolveQuo(jmvcore::enquo(generalModerators))
    if ( ! missing(generalCovariates)) generalCovariates <- jmvcore::resolveQuo(jmvcore::enquo(generalCovariates))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL),
            `if`( ! missing(m1), m1, NULL),
            `if`( ! missing(m2), m2, NULL),
            `if`( ! missing(y), y, NULL),
            `if`( ! missing(w), w, NULL),
            `if`( ! missing(covM1), covM1, NULL),
            `if`( ! missing(covM2), covM2, NULL),
            `if`( ! missing(covY), covY, NULL),
            `if`( ! missing(generalMediators), generalMediators, NULL),
            `if`( ! missing(generalModerators), generalModerators, NULL),
            `if`( ! missing(generalCovariates), generalCovariates, NULL))


    options <- pathsOptions$new(
        x = x,
        m1 = m1,
        m2 = m2,
        y = y,
        w = w,
        p_x_m1 = p_x_m1,
        p_x_m2 = p_x_m2,
        p_m1_m2 = p_m1_m2,
        p_x_y = p_x_y,
        p_m1_y = p_m1_y,
        p_m2_y = p_m2_y,
        p_w_m1 = p_w_m1,
        p_w_m2 = p_w_m2,
        p_w_y = p_w_y,
        mod_x_m1 = mod_x_m1,
        mod_x_m2 = mod_x_m2,
        mod_m1_m2 = mod_m1_m2,
        mod_x_y = mod_x_y,
        mod_m1_y = mod_m1_y,
        mod_m2_y = mod_m2_y,
        robust = robust,
        draws = draws,
        seed = seed,
        confidence = confidence,
        probes = probes,
        showDetails = showDetails,
        showCovariance = showCovariance,
        covM1 = covM1,
        covM2 = covM2,
        covY = covY,
        modelMode = modelMode,
        generalMediators = generalMediators,
        generalModerators = generalModerators,
        generalCovariates = generalCovariates,
        generalPaths = generalPaths,
        generalModerations = generalModerations,
        generalProbesW = generalProbesW,
        generalProbesZ = generalProbesZ,
        generalProbesV = generalProbesV,
        categoricalCoding = categoricalCoding,
        outcomeFamily = outcomeFamily,
        logisticEvent = logisticEvent,
        showEffectPlot = showEffectPlot,
        showInteractionPlot = showInteractionPlot,
        showJNPlot = showJNPlot,
        plotInteractionMode = plotInteractionMode,
        plotInteractionPage = plotInteractionPage,
        plotEffectKind = plotEffectKind,
        plotEffectPage = plotEffectPage,
        plotSource = plotSource,
        plotTarget = plotTarget,
        plotModerator = plotModerator,
        plotCondition = plotCondition,
        plotContrast = plotContrast,
        plotResponseScale = plotResponseScale)

    analysis <- pathsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

